/**
 * WHY this file exists:
 * Pure, stateless rendering pipeline:
 *   CharacterReadModel → Satori SVG → Resvg PNG Buffer
 *
 * The service injects no Prisma, no Redis, no HTTP client. All I/O is in the
 * controller (slug resolution) and in og.fonts.ts (Google Fonts fetch, cached
 * in memory after the first call). The service itself is free of side-effects
 * and trivially unit-testable.
 *
 * Failure strategy:
 *   - If the render pipeline throws (font load failure, Satori template error,
 *     Resvg WASM issue), the service logs the error and returns a hardcoded
 *     fallback PNG. The HTTP response is still 200 — the OG image is a
 *     convenience feature, not a critical path.
 */

import { Injectable, Logger } from '@nestjs/common';
import satori from 'satori';
import { Resvg } from '@resvg/resvg-js';

import type { CharacterReadModel } from '../../characters/domain/character.ports';
import { loadOgFonts } from './og.fonts';
import { buildCharacterOgElement } from './templates/character-og';

/** OG card dimensions — fixed per spec. */
const OG_WIDTH = 1200;
const OG_HEIGHT = 630;

/**
 * Fallback PNG: solid #0B0E2C (color.surface.void) 1200×630 card, generated
 * offline and embedded as base64 so the endpoint never returns an error to
 * crawlers even when fonts or rendering fail.
 *
 * To regenerate (requires Node.js built-ins only):
 *   node scripts/gen-fallback-og.js > /dev/null  # outputs base64 to stdout
 *
 * Dimensions: 1200×630, RGBA, deflate-compressed IDAT.
 */
// prettier-ignore
const FALLBACK_PNG_B64 =
  '';

const FALLBACK_PNG: Buffer = Buffer.from(FALLBACK_PNG_B64, 'base64');

@Injectable()
export class OgService {
  private readonly logger = new Logger(OgService.name);

  /**
   * Render a 1200×630 PNG card for the given character.
   *
   * Returns the fallback PNG buffer if rendering fails — never throws.
   */
  async renderCharacter(
    character: Pick<CharacterReadModel, 'name' | 'concept' | 'iconId'>,
  ): Promise<Buffer> {
    try {
      return await this.doRender(character);
    } catch (error) {
      this.logger.error(
        `OG render failed for character "${character.name}" — returning fallback PNG`,
        error instanceof Error ? error.stack : String(error),
      );
      return FALLBACK_PNG;
    }
  }

  private async doRender(
    character: Pick<CharacterReadModel, 'name' | 'concept' | 'iconId'>,
  ): Promise<Buffer> {
    const fonts = await loadOgFonts();
    const element = buildCharacterOgElement(character);

    const svg = await satori(element, {
      width: OG_WIDTH,
      height: OG_HEIGHT,
      fonts,
    });

    const resvg = new Resvg(svg, {
      fitTo: { mode: 'width', value: OG_WIDTH },
    });
    const pngData = resvg.render();
    return Buffer.from(pngData.asPng());
  }

  /**
   * Expose the fallback PNG for testing.
   * Allows snapshot tests to assert non-empty pixel sum on the fallback as well.
   */
  static get fallbackPng(): Buffer {
    return FALLBACK_PNG;
  }
}
